		/** 
		 * Tests creating a new Regulation.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Regulation");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Regulation" );

			try {            
				Regulation entity = RegulationService.getRegulationInstance().createRegulation( generateNewEntity() );
				thePrimaryKey = entity.getRegulationId();
				LOGGER.info( "-- Successfully created a Regulation with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Regulation. 
		 */
		public Regulation testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Regulation" );

			Regulation entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Regulation with primary key" );
			msg.append( thePrimaryKey );
			
			RegulationFetchOneSummary fetchOneSummary = new RegulationFetchOneSummary( thePrimaryKey );

			try {
				entity = RegulationService.getRegulationInstance().getRegulation( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Regulation " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Regulation.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Regulation." );

			StringBuilder msg = new StringBuilder( "Failed to update a Regulation : " );        
			Regulation entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Regulation." );

				// for use later on...
				thePrimaryKey = entity.getRegulationId();

				RegulationService proxy = RegulationService.getRegulationInstance();            
				proxy.updateRegulation( entity );   

				LOGGER.info( "-- Successfully saved Regulation - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Regulation.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Regulation." );

			try{
			    Regulation entity = testRead(); 
				RegulationService.getRegulationInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Regulation with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Regulation with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Regulations.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Regulations:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Regulation : " );        
			List<Regulation> collection  = null;

			try {
				// call the static get method on the RegulationService
				collection = RegulationService.getRegulationInstance().getAllRegulation();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Regulation entity = null;            
					Iterator<Regulation> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getRegulationId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

